package claudecode

import (
    "bytes"
    "context"
    "errors"
    "io"
    "os"
    "os/exec"
    "strings"

    "github.com/entireio/cli/cmd/entire/cli/agent"
)

// GenerateText is the non-streaming convenience wrapper. It delegates to
// GenerateTextStreaming with no progress callback.
func (c *ClaudeCodeAgent) GenerateText(ctx context.Context, prompt, model string) (string, error) {
    return c.GenerateTextStreaming(ctx, prompt, model, nil)
}

// GenerateTextStreaming runs the Claude CLI in stream-json mode, dispatches
// progress events to the optional callback, and returns the final result text.
// On failure, returns *ClaudeError so callers can map kinds to user messages.
func (c *ClaudeCodeAgent) GenerateTextStreaming(
    ctx context.Context,
    prompt, model string,
    progress agent.ProgressFn,
) (string, error) {
    claudePath := "claude"
    if model == "" {
        model = "haiku"
    }

    commandRunner := c.CommandRunner
    if commandRunner == nil {
        commandRunner = exec.CommandContext
    }

    cmd := commandRunner(ctx, claudePath,
        "--print",
        "--output-format", "stream-json",
        "--include-partial-messages",
        "--verbose",
        "--model", model,
        "--setting-sources", "")

    cmd.Dir = os.TempDir()
    cmd.Env = stripGitEnv(os.Environ())
    cmd.Stdin = strings.NewReader(prompt)

    stdout, err := cmd.StdoutPipe()
    if err != nil {
        return "", &ClaudeError{Kind: ClaudeErrorUnknown, Cause: err}
    }
    var stderr bytes.Buffer
    cmd.Stderr = &stderr

    if err := cmd.Start(); err != nil {
        if isExecError(err) {
            return "", &ClaudeError{Kind: ClaudeErrorCLIMissing, Cause: err}
        }
        return "", &ClaudeError{Kind: ClaudeErrorUnknown, Cause: err}
    }

    final, parseErr := streamClaudeResponse(stdout, makeProgressDispatcher(progress))
    waitErr := cmd.Wait()

    if ctxErr := ctx.Err(); ctxErr != nil {
        return "", ctxErr // sentinel passthrough for context cancel/deadline
    }

    if waitErr != nil {
        if isExecError(waitErr) {
            return "", &ClaudeError{Kind: ClaudeErrorCLIMissing, Cause: waitErr}
        }
    }

    // Prefer the structured envelope when we have one.
    if final != nil {
        if !final.IsError {
            if final.Result != nil {
                if progress != nil {
                    progress(agent.GenerationProgress{
                        Phase:        agent.PhaseDone,
                        OutputTokens: outputTokensFromUsage(final.Usage),
                        DurationMs:   final.DurationMs,
                    })
                }
                return *final.Result, nil
            }
            return "", &ClaudeError{Kind: ClaudeErrorUnknown, Message: "claude returned empty result"}
        }
        result := ""
        if final.Result != nil {
            result = *final.Result
        }
        exitCode := 0
        if exitErr := new(exec.ExitError); errors.As(waitErr, &exitErr) {
            exitCode = exitErr.ExitCode()
        }
        return "", classifyEnvelopeError(result, final.APIErrorStatus, exitCode)
    }

    // No envelope: fall back to stderr classification when we have a non-zero exit.
    if waitErr != nil {
        exitCode := -1
        if exitErr := new(exec.ExitError); errors.As(waitErr, &exitErr) {
            exitCode = exitErr.ExitCode()
        }
        return "", classifyStderrError(stderr.String(), exitCode)
    }

    if parseErr != nil {
        return "", &ClaudeError{Kind: ClaudeErrorUnknown, Message: parseErr.Error(), Cause: parseErr}
    }
    return "", &ClaudeError{Kind: ClaudeErrorUnknown, Message: "claude exited without producing a result"}
}

// makeProgressDispatcher returns a per-event handler that translates raw
// stream events into agent.GenerationProgress callbacks.
func makeProgressDispatcher(progress agent.ProgressFn) func(StreamEvent) {
    if progress == nil {
        return func(StreamEvent) {}
    }
    var outputTokensEstimate int
    return func(ev StreamEvent) {
        switch {
        case ev.Type == "system" && ev.Subtype == "status" && ev.Status == "requesting":
            progress(agent.GenerationProgress{Phase: agent.PhaseConnecting})
        case ev.Type == "stream_event" && ev.Event.Type == "message_start":
            p := agent.GenerationProgress{Phase: agent.PhaseFirstToken, TTFTms: ev.Event.TTFTms}
            if ev.Event.Message != nil && ev.Event.Message.Usage != nil {
                p.InputTokens = ev.Event.Message.Usage.InputTokens
                p.CachedInputTokens = ev.Event.Message.Usage.CacheReadInputTokens
            }
            progress(p)
        case ev.Type == "stream_event" && ev.Event.Type == "content_block_delta" && ev.Event.Delta != nil:
            // Estimate output tokens from delta text length (chars/4 rough heuristic
            // for English; conservative — the real count comes in the result event).
            text := ev.Event.Delta.Text
            if text == "" {
                text = ev.Event.Delta.Thinking
            }
            outputTokensEstimate += len(text) / 4
            progress(agent.GenerationProgress{Phase: agent.PhaseGenerating, OutputTokens: outputTokensEstimate})
        }
    }
}

func outputTokensFromUsage(u *Usage) int {
    if u == nil {
        return 0
    }
    return u.OutputTokens
}

// isExecError returns true if err originates from the OS being unable to
// locate or invoke the subprocess binary.
func isExecError(err error) bool {
    var execErr *exec.Error
    if errors.As(err, &execErr) {
        return true
    }
    // Some platforms surface "no such file" via PathError when StdoutPipe
    // is asked for a process that never started.
    return errors.Is(err, exec.ErrNotFound)
}

// stripGitEnv returns a copy of env with all GIT_* variables removed.
// This prevents a subprocess from discovering or modifying the parent's git repo.
func stripGitEnv(env []string) []string {
    filtered := make([]string, 0, len(env))
    for _, e := range env {
        if !strings.HasPrefix(e, "GIT_") {
            filtered = append(filtered, e)
        }
    }
    return filtered
}

// io is imported in case future helpers need it; remove if unused at lint time.
var _ = io.EOF
